import type { LocalDate } from "@/features/habits/domain/dates"
import type { Habit, HabitEntry, HabitsState } from "@/features/habits/domain/types"
import type { Op } from "./types"

/**
 * Safe migration of browser demo data into an account.
 *
 * Rules (M2 requirement: never import fictional data automatically):
 * - Nothing happens without an explicit selection by the user.
 * - Entries generated by the demo seed (`opId` starting with "demo:") are never imported.
 * - Demo template habits ("demo-…") import only their definition, starting today;
 *   their fabricated history is dropped.
 * - Habits the user created in the demo keep their schedule versions, and
 *   optionally the records the user actually made.
 * - Ids are deterministic per account, so running the import twice cannot
 *   create duplicates (server ledger + idempotent habit.create).
 */

export const isDemoTemplate = (h: Habit) => h.id.startsWith("demo-")
export const isSeededEntry = (e: HabitEntry) => e.opId.startsWith("demo:")

export interface ImportCandidate {
  habit: Habit
  template: boolean
  /** Records the user really made for this habit (never seeded ones). */
  userEntries: HabitEntry[]
}

export function importCandidates(demo: HabitsState, today: LocalDate): ImportCandidate[] {
  return demo.habits
    .filter((h) => !h.archivedOn || h.archivedOn > today)
    .map((habit) => {
      const template = isDemoTemplate(habit)
      const start = template ? today : habit.startDate
      const userEntries = Object.values(demo.entries).filter(
        (e) => e.habitId === habit.id && !isSeededEntry(e) && e.date >= start && e.date <= today
      )
      return { habit, template, userEntries }
    })
}

export interface ImportPlan {
  ops: Op[]
  habits: number
  entries: number
  skippedSeeded: number
}

export function planDemoImport(
  demo: HabitsState,
  opts: {
    selected: ReadonlySet<string>
    includeUserEntries: boolean
    today: LocalDate
    /** Deterministic id for a local habit in this account. */
    idFor: (localHabitId: string) => string
  }
): ImportPlan {
  const ops: Op[] = []
  let entries = 0
  let skippedSeeded = 0

  for (const c of importCandidates(demo, opts.today)) {
    if (!opts.selected.has(c.habit.id)) continue
    const h = c.habit
    const id = opts.idFor(h.id)
    const start = c.template ? opts.today : h.startDate
    const current = h.schedule[h.schedule.length - 1].rule
    const versions = c.template
      ? [{ valid_from: opts.today, rule: current }]
      : h.schedule.map((v) => ({ valid_from: v.validFrom, rule: v.rule }))

    ops.push({
      type: "habit.create",
      op_id: `import:${id}:create`,
      habit: {
        id,
        title: h.name,
        icon: h.icon,
        dimension: h.dimensionId,
        habit_type: h.type,
        unit: h.type === "binary" ? null : (h.unit ?? null),
        target_value: h.type === "binary" ? null : (h.target ?? null),
        target_direction: h.type === "binary" ? null : (h.direction ?? "at_least"),
        start_date: start,
      },
      versions,
    })

    skippedSeeded += Object.values(demo.entries).filter((e) => e.habitId === h.id && isSeededEntry(e)).length
    if (!opts.includeUserEntries) continue
    for (const e of c.userEntries) {
      ops.push({
        type: "entry.set",
        op_id: `import:${id}:${e.date}`,
        habit_id: id,
        local_date: e.date,
        value: e.value,
        client_updated_at: e.updatedAt,
        base_seq: null,
      })
      entries++
    }
  }
  return { ops, habits: ops.filter((o) => o.type === "habit.create").length, entries, skippedSeeded }
}
